        transport: { en: 'Private car (100 km, ~2 hrs)', es: 'Vehículo privado (100 km, ~2 h)' },
        notes: { en: 'Matrimandir open 15:30–16:30.', es: 'Matrimandir abierto de 15:30 a 16:30.' },
        isOptional: false,
