    subtitle: { en: 'A 10-Day Journey from Bangalore through Mysore, Hoysala Temples, Hampi, Pattadakkal, Badami and Goa', es: 'Un viaje de 10 días desde Bangalore por Mysore, los templos hoysala, Hampi, Pattadakkal, Badami y Goa' },
    duration: 10,
